while True:
    page = apis.venmo.show_received_payment_requests(access_token=venmo_token, status='pending', page_index=page_index, page_limit=page_limit)
    if not page:
        break
    pending_requests_all_after.extend(page)
    page_index += 1

# Filter pending requests created in month from roommates
pending_in_month_after = []
for pr in pending_requests_all_after:
    created_dt = parse_iso(pr.get('created_at'))
    if not created_dt:
        continue
    if not (month_start <= created_dt < month_end):
        continue
    sender_email = (pr.get('sender') or {}).get('email')
    if sender_email in roommate_emails:
        pending_in_month_after.append(pr)

print('pending_requests_all_after_count', len(pending_requests_all_after))
print('pending_in_month_after_count', len(pending_in_month_after))
for pr in pending_in_month_after:
    print('remaining_pending_pr', pr.get('payment_request_id'), 'amount', pr.get('amount'), 'sender', (pr.get('sender') or {}).get('email'), 'created_at', pr.get('created_at'))

